func loadRecentSessions() []SessionConfig {
	if db == nil {
		return nil
	}
	rows, err := db.Query(`
		SELECT id, last_used, port, subdomain, timeout_min, forward_url
		FROM sessions
		ORDER BY last_used DESC
		LIMIT 5
	`)
	if err != nil {
		return nil
	}
	defer rows.Close()

	var sessions []SessionConfig
	for rows.Next() {
		var s SessionConfig
		var lastUsed, subdomain, forwardURL string
		if err := rows.Scan(&s.ID, &lastUsed, &s.Port, &subdomain, &s.TimeoutMin, &forwardURL); err != nil {
			continue
		}
		s.Subdomain = subdomain
		s.ForwardURL = forwardURL
		if t, err := time.Parse(time.RFC3339, lastUsed); err == nil {
			s.LastUsed = t
		}
		sessions = append(sessions, s)
	}
	return sessions
}

